#include <stdio.h>

#define CACHE_BYTES 1024
#define BLOCK       16
#define LINES       (CACHE_BYTES / BLOCK)

static int tag_of[LINES];
static int valid[LINES];

int main(void) {
    unsigned addrs[] = {0x0000, 0x0010, 0x0020, 0x0000, 0x0400, 0x0410,
                        0x0000, 0x0010, 0x0800, 0x0810, 0x0000};
    int n = (int)(sizeof addrs / sizeof addrs[0]);
    int hits = 0, misses = 0, i;

    printf("=== direct-mapped cache ===\n");
    printf("  capacity %d B, block %d B -> %d lines\n", CACHE_BYTES, BLOCK, LINES);
    printf("  address split: tag = bits 31:10, index = bits 9:4, offset = bits 3:0\n\n");
    printf("  address    tag  index  offset   result\n");

    for (i = 0; i < n; i++) {
        unsigned a = addrs[i];
        unsigned offset = a % BLOCK;
        unsigned index = (a / BLOCK) % LINES;
        unsigned tag = (a / BLOCK) / LINES;
        const char *res;

        if (valid[index] && tag_of[index] == (int)tag) {
            res = "HIT";
            hits++;
        } else {
            res = "MISS";
            misses++;
            valid[index] = 1;
            tag_of[index] = (int)tag;
        }
        printf("  0x%04X   %5u  %5u  %6u   %s\n", a, tag, index, offset, res);
    }

    printf("\nhits=%d misses=%d  hit rate=%.1f%%\n", hits, misses, 100.0 * hits / n);
    printf("\nreading the trace:\n");
    printf("  0x0000 is revisited immediately -> HIT (temporal locality)\n");
    printf("  0x0400 has the same index 0 as 0x0000 -> it evicts it, and the next 0x0000 MISSES\n");
    printf("  0x0800 also lands on index 0 -> three blocks fight over one line\n");
    printf("  that is a CONFLICT miss: a 2-way set-associative cache would remove it entirely\n");
    return 0;
}
